// ---------- 预览入口进白名单的前提：它碰不到发送代码 ----------

/** 顺着 import 走一遍，返回这个模块传递依赖到的全部本地脚本。 */
function importGraph(entry, seen = new Set()) {
  const abs = path.resolve("scripts", entry);
  if (seen.has(abs)) return seen;
  seen.add(abs);
  let src;
  try { src = fs.readFileSync(abs, "utf-8"); } catch { return seen; }
  for (const m of src.matchAll(/^\s*import[^"']*["'](\.\/[^"']+)["']/gm)) {
    importGraph(m[1].replace("./", ""), seen);
  }
  for (const m of src.matchAll(/await import\(\s*["'](\.\/[^"']+)["']/g)) {
    importGraph(m[1].replace("./", ""), seen);
  }
  return seen;
}

test("bind-preview 的依赖图里没有 outbound —— 白名单条目必须名副其实", () => {
  const g = [...importGraph("bind-preview.mjs")].map((f) => path.basename(f));
  assert.ok(!g.includes("outbound.mjs"),
    "预览入口不能传递依赖到能发消息的代码，实际依赖：" + g.join(", "));
  assert.ok(!g.includes("drain-outbox.mjs"), "也不能间接拉进发布器：" + g.join(", "));
  assert.ok(g.includes("bind-compose.mjs") && g.includes("chain-template.mjs"), "该有的还得有");
});

test("bind-preview 的代码里不出现任何执行外部命令的手段", () => {
  // 先剥注释：文件头那段说明本来就要提 outbound 依赖 execFileSync 这件事，
  // 提到它和用它是两回事，检查用的必须是代码。
  const code = fs.readFileSync(path.resolve("scripts", "bind-preview.mjs"), "utf-8")
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .replace(/^\s*\/\/.*$/gm, "");
  for (const bad of ["child_process", "execFile", "execSync", "spawn", "lark-cli"]) {
    assert.ok(!code.includes(bad), "预览入口的代码里不该出现 " + bad);
  }
});

test("对照：bind-project 确实依赖 outbound（否则上面那条测试是空的）", () => {
  const g = [...importGraph("bind-project.mjs")].map((f) => path.basename(f));
  assert.ok(g.includes("outbound.mjs"), "真发那条路径本来就该依赖 outbound");
});

// ---------- 入站多绑定路由 ----------

function routeFixture(projects) {
  const home = fs.mkdtempSync(path.join(os.tmpdir(), "bridge-cc-route-"));
  const regFile = path.join(home, "registry.json");
  const tplFile = path.join(home, "chain-config.json");
  fs.writeFileSync(tplFile, JSON.stringify(TPL));
  const entries = projects.map((p) => {
    const root = fs.mkdtempSync(path.join(os.tmpdir(), "bridge-cc-p-"));
    return { id: p.id, root, root_message_id: "om_" + p.id,
      expires_at: "2099-01-01T00:00:00Z", ...p.extra };
  });
  fs.writeFileSync(regFile, JSON.stringify({ projects: entries }));
  return { regFile, tplFile, entries };
}

const files = (f) => ({ registryFile: f.regFile, templateFile: f.tplFile });

test("session_id 对上哪个项目就路由到哪个", () => {
  const f = routeFixture([
    { id: "a", extra: { session_id: "session_a", inbound_state: "bound" } },
    { id: "b", extra: { session_id: "session_b", inbound_state: "bound" } },
  ]);
  const r = findBindingForSession({ sessionId: "session_b", ...files(f) });
  assert.equal(r.ok, true);
  assert.equal(r.id, "b");
  assert.equal(r.root, f.entries[1].root);
});

test("认不出的 session → 不路由（绝不退回默认项目）", () => {
  const f = routeFixture([{ id: "a", extra: { session_id: "session_a", inbound_state: "bound" } }]);
  const r = findBindingForSession({ sessionId: "session_unknown", ...files(f) });
  assert.equal(r.ok, false);
  assert.equal(r.reason, "no_binding_for_session");
});

test("还没绑的项目（session_id 为 null）永远不会被 session 路由选中", () => {
  const f = routeFixture([{ id: "a", extra: {} }]);
  for (const sid of ["session_x", "null", ""]) {
    assert.equal(findBindingForSession({ sessionId: sid, ...files(f) }).ok, false, sid);
  }
});

test("绑定被停用（status 非 active）→ 不路由", () => {
  const f = routeFixture([
    { id: "a", extra: { session_id: "session_a", inbound_state: "bound", status: "closed" } },
  ]);
  assert.equal(findBindingForSession({ sessionId: "session_a", ...files(f) }).ok, false);
});

// ---------- 第二段绑定：@ 一下就完成 ----------

const NOW2 = Date.parse("2026-08-20T12:00:00Z");
const okEvent = {
  message_id: "msg_new", session_id: "session_fresh", sender_id: TPL.frank_sender_id,
  created_at_ms: NOW2 - 3000, content: '<at id="ou_t">T</at>',
};

const pendingOf = (f, extra = {}) => {
  const reg = JSON.parse(fs.readFileSync(f.regFile, "utf-8"));
  reg.projects[0] = { ...reg.projects[0], inbound_state: "pending",
    bound_at: new Date(NOW2 - 60_000).toISOString(), ...extra };
  fs.writeFileSync(f.regFile, JSON.stringify(reg));
  return findPendingBinding({ ...files(f), now: NOW2 });
};

test("全机唯一那份待绑定 + 授权发送者 + 真实 mention → 放行", () => {
  const f = routeFixture([{ id: "a", extra: {} }]);
  const r = evaluatePromotion({ event: okEvent, template: TPL, pending: pendingOf(f), now: NOW2 });
  assert.equal(r.ok, true);
  assert.equal(r.id, "a");
});

test("不是 Frank 发的 → 拒（绑定前这道闸就在）", () => {
  const f = routeFixture([{ id: "a", extra: {} }]);
  const r = evaluatePromotion({
    event: { ...okEvent, sender_id: "9999" }, template: TPL, pending: pendingOf(f), now: NOW2 });
  assert.equal(r.ok, false);
  assert.equal(r.reason, PROMOTE_REJECT.SENDER_NOT_FRANK);
});

test("没有真实 <at> → 拒；手打的 @名字 不算", () => {
  const f = routeFixture([{ id: "a", extra: {} }]);
  for (const content of ["随便说说", "@T 干活", '<at id="ou_other">别人</at>']) {
    const r = evaluatePromotion({
      event: { ...okEvent, content }, template: TPL, pending: pendingOf(f), now: NOW2 });
    assert.equal(r.reason, PROMOTE_REJECT.TRANSPORT_NOT_MENTIONED, content);
  }
});

test("#R11 P1-2：promotion 底层不豁免 @ —— 已验证私聊（登记表命中）在认领路径仍必须真实 @，无 @ 一律 transport_not_mentioned", () => {
  const f = routeFixture([{ id: "a", extra: {} }]);
  const whitelist = { ...TPL, verified_p2p_chat_ids: ["oc_p2pverified"] };
  // 私聊 env（chat≠模板 + thread 缺失）且已在白名单里，恰好落在"私聊豁免 @"那类误判的点上；
  // 认领必须看真实 @ —— 早分流漏接时，私聊不能凭"无 @"从私聊认领 pending。
  const priv = { sender_id: TPL.frank_sender_id, content: "能收到吗", created_at_ms: NOW2 };
  const r = evaluatePromotion({
    event: priv, template: whitelist, pending: pendingOf(f), now: NOW2,
    env: { AILY_CLI_CHANNEL_CHAT_ID: "oc_p2pverified" } });
  assert.equal(r.ok, false);
  assert.equal(r.reason, PROMOTE_REJECT.TRANSPORT_NOT_MENTIONED);
});

test("消息太旧 → 拒，防重放", () => {
  const f = routeFixture([{ id: "a", extra: {} }]);
  const r = evaluatePromotion({
    event: { ...okEvent, created_at_ms: NOW2 - 60 * 60 * 1000 },
    template: TPL, pending: pendingOf(f), now: NOW2 });
  assert.equal(r.reason, PROMOTE_REJECT.STALE_MESSAGE);
});

test("没有待绑定 → 拒，不去乱认一个项目", () => {
  const f = routeFixture([{ id: "a", extra: { session_id: "session_a", inbound_state: "bound" } }]);
  const r = evaluatePromotion({
    event: okEvent, template: TPL, pending: findPendingBinding({ ...files(f), now: NOW2 }), now: NOW2 });
  assert.equal(r.reason, PROMOTE_REJECT.NO_PENDING);
});

test("同时有两份待绑定 → 拒。认领靠的就是「只有一份」这个前提", () => {
  const f = routeFixture([{ id: "a", extra: {} }, { id: "b", extra: {} }]);
  const reg = JSON.parse(fs.readFileSync(f.regFile, "utf-8"));
  for (const p of reg.projects) { p.inbound_state = "pending"; p.bound_at = new Date(NOW2 - 60_000).toISOString(); }
  fs.writeFileSync(f.regFile, JSON.stringify(reg));
  const pending = findPendingBinding({ ...files(f), now: NOW2 });
  assert.equal(pending.reason, PROMOTE_REJECT.MULTIPLE_PENDING);
  const r = evaluatePromotion({ event: okEvent, template: TPL, pending, now: NOW2 });
  assert.equal(r.reason, PROMOTE_REJECT.MULTIPLE_PENDING);
});

test("待绑定不过期：没有显式截止的登记行 30 天后仍可认领；写了显式截止且已过 → 过期，重新接入", () => {
  const f = routeFixture([{ id: "a", extra: {} }]);
  const DAY = 24 * 3600000;
  const old = pendingOf(f, { bound_at: new Date(NOW2 - 30 * DAY).toISOString(), pending_expires_at: null });
  assert.equal(old.ok, true, JSON.stringify(old));
  const legacyNoField = pendingOf(f, { bound_at: new Date(NOW2 - 30 * DAY).toISOString(), pending_expires_at: undefined });
  assert.equal(legacyNoField.ok, true, "老登记行没这个字段 = 不过期：" + JSON.stringify(legacyNoField));
  const explicitPast = pendingOf(f, { bound_at: new Date(NOW2 - 2 * DAY).toISOString(), pending_expires_at: new Date(NOW2 - 1000).toISOString() });
  assert.equal(explicitPast.reason, PROMOTE_REJECT.PENDING_EXPIRED);
  const explicitFuture = pendingOf(f, { bound_at: new Date(NOW2 - 2 * DAY).toISOString(), pending_expires_at: new Date(NOW2 + 1000).toISOString() });
  assert.equal(explicitFuture.ok, true);
});

// ---- P1-2（F4）：认领在 chat/sender/body(码)/thread_root 四维真实匹配。----
// sender/@/body(码) 已有闸兜底；thread_root 由 pending 锚定（root_message_id=matched_om），不经 env
//   （AILY_CLI_CHANNEL_THREAD_ID 只是 Aily 命名空间 thread 标识，不是飞书 thread/root locator——
//   channel-locator-verdict.md §2）。这里补 **chat** 维：env chat 存在且与待绑定群不一致 → 拒。
test("P1-1 F4（claude）：完整四维——绑定码命中 + env chat = target + owner/@/新鲜 → 放行且产完整 f4", () => {
  const f = pendingFixture([{ id: "a", token: "aaaaaa" }]);
  const content = '<at id="ou_t">T</at>\n\n**[引用]**\n🌉 a\n绑定码    aaaaaa';
  const pending = findPendingBinding({ content, ...f, now: NOW2 });
  assert.equal(pending.ok, true, "pending ok：" + JSON.stringify(pending));
  assert.equal(pending.matchedBy, "quoted_binding_token", "绑定码精确命中");
  const r = evaluatePromotion({
    event: { message_id: "m", session_id: "s", sender_id: TPL.frank_sender_id, created_at_ms: NOW2 - 3000, content },
    template: TPL, pending, now: NOW2, env: { AILY_CLI_CHANNEL_CHAT_ID: TPL.chat_id } });
  assert.equal(r.ok, true, JSON.stringify(r));
  assert.equal(typeof r.f4, "object", "产出封闭 f4 产物：" + JSON.stringify(r.f4));
  assert.equal(typeof r.f4.matched_om, "string", "matched_om=被认领根消息 om");
  assert.deepEqual(r.f4.matched_fields, ["chat_id", "sender", "body", "thread_root"], "标准四项（G15 封闭四项）");
});

test("P1-1 F4（claude）：chat 不匹配（env 是别的群）→ 拒（不能把 pending 从错误群里绑过来）", () => {
  const f = routeFixture([{ id: "a", extra: {} }]);
  const pending = pendingOf(f);
  const r = evaluatePromotion({
    event: okEvent, template: TPL, pending, now: NOW2,
    env: { AILY_CLI_CHANNEL_CHAT_ID: "oc_othergroup" } });
  assert.equal(r.ok, false);
  assert.equal(r.reason, PROMOTE_REJECT.CHAT_MISMATCH);
});

test("P1-1 F4（claude）反向探针①：env chat 缺失 → 不硬拒但 f4=null（不折成完整 pairing proof）", () => {
  const f = pendingFixture([{ id: "a", token: "aaaaaa" }]);
  const content = '<at id="ou_t">T</at>\n\n**[引用]**\n🌉 a\n绑定码    aaaaaa'; // 绑定码命中，唯一差 env chat
  const pending = findPendingBinding({ content, ...f, now: NOW2 });
  assert.equal(pending.matchedBy, "quoted_binding_token");
  const r = evaluatePromotion({ event: okEvent, template: TPL, pending, now: NOW2, env: {} });
  assert.equal(r.ok, true, "缺 env chat 不拒绝（ailly 真实认领就没有它走）");
  assert.equal(r.f4, null, "env chat 缺失 → f4=null（未受验不产完整 F4）");
});

test("守卫①（claude）：plain 真无码单候选（only_pending + token:null）→ f4=null（owner_root_no_token_v1 停止生产，无码不再产配对证明）", () => {
  const f = pendingFixture([{ id: "a", token: null }]);
  const content = '<at id="ou_t">T</at> 干活'; // 无绑定码
  const pending = findPendingBinding({ content, ...f, now: NOW2 });
  assert.equal(pending.ok, true);
  assert.equal(pending.matchedBy, "only_pending");
  assert.equal(pending.generation.pending_token, null, "fixture 真无码");
  const r = evaluatePromotion({ event: okEvent, template: TPL, pending, now: NOW2, env: { AILY_CLI_CHANNEL_CHAT_ID: TPL.chat_id } });
  assert.equal(r.ok, true, "only_pending 仍放行（只有一份待绑定 + 无码无到期），但不产证明");
  assert.equal(r.f4, null, "无码单候选 → f4=null（#守卫①：root-blind Aily 下无诚实 thread_root，owner_root_no_token_v1 停止生产）");
});

test("P1-1-d F4（claude）反向探针：无码单候选但有码在 pending → f4=null（裁定 d 条件②）", () => {
  const f = pendingFixture([{ id: "a", token: "aaaaaa" }]); // generation 有码，但正文未引用
  const content = '<at id="ou_t">T</at> 干活';
  const pending = findPendingBinding({ content, ...f, now: NOW2 });
  assert.equal(pending.matchedBy, "only_pending");
  const r = evaluatePromotion({ event: okEvent, template: TPL, pending, now: NOW2, env: { AILY_CLI_CHANNEL_CHAT_ID: TPL.chat_id } });
  assert.equal(r.ok, true, "有码未引用的单候选仍放宽行（不硬拒）");
  assert.equal(r.f4, null, "pending_token 非 null → 不产 no-token proof（既不是 token 认领也没有可验证的无 token 状态）");
});

test("P1-1①（claude）：无码单候选 + env chat 缺失 → f4=null（chat 维必须来自事件侧受验 locator，不能因『全机唯一 pending』就自证来源）", () => {
  const f = pendingFixture([{ id: "a", token: null }]);
  const content = '<at id="ou_t">T</at> 干活'; // 无绑定码
  const pending = findPendingBinding({ content, ...f, now: NOW2 });
  assert.equal(pending.ok, true);
  assert.equal(pending.matchedBy, "only_pending");
  // 本消息所在群的受验 locator 缺失（env 无 AILY_CLI_CHANNEL_CHAT_ID）→ 无法证明 chat 维来源 → f4=null
  const r = evaluatePromotion({ event: okEvent, template: TPL, pending, now: NOW2, env: {} });
  assert.equal(r.ok, true, "缺 env chat 本身不拒（消息仍有效），但不得产未受验的配对证明");
  assert.equal(r.f4, null, "无码单候选 + env chat 缺失 → f4=null（chat 维未受验，不产 owner_root_no_token_v1）");
});

test("首次绑定走真实 newRegistryEntry → pendingDeadline：不写截止，任何时候都可认领", () => {
  const f = routeFixture([{ id: "a", extra: {} }]);
  const DAY = 24 * 3600000;
  const mk = (now) => newRegistryEntry({ root: "/tmp/win", name: "win", purpose: null, token: "aaa111", rootMessageId: "om_win", now });
  const fresh = mk(NOW2 - 60_000);
  assert.equal(fresh.pending_expires_at, null, "登记行显式 null：不过期");
  assert.equal(pendingOf(f, { bound_at: fresh.bound_at, pending_expires_at: fresh.pending_expires_at }).ok, true);
  const ancient = mk(NOW2 - 400 * DAY);
  assert.equal(pendingOf(f, { bound_at: ancient.bound_at, pending_expires_at: ancient.pending_expires_at }).ok, true, "400 天也不过期");
});

