  const src = fs.readFileSync(path.resolve("scripts", "install-outbound.mjs"), "utf-8") + "\n" + fs.readFileSync(path.resolve("scripts", "install-projection.mjs"), "utf-8"); // 投影抽到了 install-projection.mjs，两份一起扫
