  assert.deepEqual([conflictVia.status, /自相矛盾（failed（完整）与 consumed（损坏）并存）/u.test(conflictVia.stdout)], [1, true], conflictVia.stdout);
  assert.equal(policyOf(), MAPPING_POLICY_ID);
