  const ps = () => ({ ok: true, stdout: "PID PPID COMMAND\n1 0 launchd\n10 1 node /r/current/scripts/a.mjs\n11 10 claude -p\n12 1 node /elsewhere/a.mjs\n20 1 node /r/current/scripts/b.mjs\n21 20 sh\n" });
