    const initOp = "00000000-0000-4000-8000-000000000001", up1 = "00000000-0000-4000-8000-000000000002", voidOp = "00000000-0000-4000-8000-000000000003";
    const vid = "ta_" + "4".repeat(32);
    const handle = "osh_" + "5".repeat(32);
