    talOk(TAL.attach({ endpointId: EP57, requestKey: "p14_att2", id, bindingTarget: TGT57(7), claimKey: CLAIM57("f"), authorizedBy: "ou_p14", anchorCandidate: "om_p14", clock: () => T0 }), "attach→A4→A3");
