    const act = talOkC(TAL.activate({ endpointId: EP57C, requestKey: "r57c_d2act", b1Id: b1b.result.created_id, a1Id: a1b.result.created_id, authorizedBy: "ou_owner57c", ...sel, clock: () => T0C }), "activate 增量 demoted");
